def _track_points(point_data_list, time_steps, backend):
    feature_matrices = []

    for t in range(time_steps):
        points_paraview = PointAndCellIds(Input=point_data_list[t].points)
        points_paraview.GenerateCellIds = 0

        points_vtk = servermanager.Fetch(points_paraview)
        numPoints = points_vtk.GetNumberOfPoints()
        ids_array = points_vtk.GetPointData().GetArray("PointIds")

        feature_matrix = np.zeros((numPoints,3))

        for idx in range(numPoints):
            point = points_vtk.GetPoint(idx)
            id_ = ids_array.GetTuple1(idx)
            feature_matrix[int(id_),:] = point

        feature_matrices.append(feature_matrix)

    coupling_matrices = []

    for t in range(time_steps-1):

        feat1 = feature_matrices[t]
        feat2 = feature_matrices[t+1]

        if backend == "emd":
            emd = ot.da.EMDTransport()
            emd.fit(Xs=feat1, Xt=feat2)
            coupling_matrices.append(emd.coupling_)
        elif backend == "sinkhorn":
            sinkhorn = ot.da.SinkhornTransport()
            sinkhorn.fit(Xs=feat1, Xt=feat2)
            coupling_matrices.append(sinkhorn.coupling_)
        elif backend == "partial":
            C = ot.dist(feat1, feat2)
            n = len(feat1)
            m = len(feat2)
            a = np.ones(n)
            b = np.ones(m)

            mass = min(n,m)

            T = ot.partial.partial_wasserstein(a, b, C, m=mass)
            coupling_matrices.append(T)

    feature_pairing = []
    first_feature = {}
    num_initial_features = coupling_matrices[0].shape[0]
    for i in range(num_initial_features):
        first_feature[i] = i

    next_feat = num_initial_features

    feature_pairing.append(first_feature)

    for t,matrix in enumerate(coupling_matrices):
        index_pairing = {}

        for i in range(matrix.shape[0]):
            future_feat = np.argmax(matrix[i,:])
            if future_feat in index_pairing:
                if matrix[i,future_feat] > matrix[index_pairing[future_feat],future_feat]:
                    index_pairing[future_feat] = i
            else:
                index_pairing[future_feat] = i

        pairing = {}

        for j in range(matrix.shape[1]):
            if j in index_pairing:
                pairing[j] = feature_pairing[t][index_pairing[j]]
            else:
                pairing[j] = next_feat
                next_feat += 1

        feature_pairing.append(pairing)

    return feature_pairing

def _generate_color_list(tracking_steps):
    max_tracking_id = max([ max(d.values()) for d in tracking_steps ])
    return random_hex_colors(max_tracking_id + 1, "point-tracking-colors")

class TrackScalarCriticalPoints(Node):

    def __init__(self, parent_node_id : str, time_steps : int, backend : str):
        if correctness_checks_on():
            if not tree.has_node(parent_node_id):
                raise Exception(f"There is no node with id {parent_node_id}")

            if backend not in options_lists["tracking"]:
                raise Exception(f"Invalid tracking backend {backend}. Valid choices are {enumerate_list(options_lists['tracking'])}")
            parent_time_steps = tree.node(parent_node_id).root_node.time_steps
            if time_steps == 0 or time_steps < -1 or time_steps > parent_time_steps:
                raise Exception(f"Invalid number of time steps. Must be between 1 and {parent_time_steps} or -1 for all time steps.")

        super().__init__(parent_node_id, types.ScalarCriticalPoints, types.TrackedScalarCriticalPoints, locals(), True, True)

        if time_steps == -1:
            self.time_steps = self.root_node.time_steps
        else:
            self.time_steps = time_steps
        self.backend = backend

    @classmethod
    def chat_description(cls):
        return "queued tracking scalar field critical points"

    @classmethod
    def description(cls):
        return 'Tracks the locations of scalar field critical points over time.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar_cp corresponding to the points that are tracked.',
            'time_steps': 'How many time steps should the tracking be computed for. Set this to -1 for all time steps.',
         'backend': 'Which backend algorithm should be used for the tracking. Choices are '
                    'OPTIONS:tracking.'}

    @classmethod
    def mandatory_parameters(cls):
        return ["time_steps", "backend"]

    def _evaluation_logic(self, parent_data, time_step):
        pairing = _track_points(parent_data, self.time_steps, self.backend)
        return types.TrackedScalarCriticalPoints(parent_data[time_step-1].points, pairing)

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):
        partial_cache.points = parent_data.points
        return partial_cache

